css:
/* EFRIS Tax Invoice — table layout only (no flexbox) so wkhtmltopdf matches the browser.
   Every table rule is scoped and sets its own borders/padding so Frappe's print styles can't bleed in. */
.efx { font-family: Arial, Helvetica, sans-serif; font-size: 10.5px; color: #1f2933; line-height: 1.45; }
.efx table { width: 100%; border-collapse: collapse; margin: 0; }
.efx td, .efx th { vertical-align: top; padding: 0; border: 0; background: none; }
.efx-label { font-size: 8.5px; font-weight: bold; text-transform: uppercase; letter-spacing: .6px; color: #6b7785; }
.efx-muted { font-size: 9px; color: #7b8794; }
.efx .r { text-align: right; }
.efx .c { text-align: center; }

.efx-warn { border: 1.5px solid #c0392b; color: #c0392b; font-weight: bold; text-align: center; padding: 5px; margin-bottom: 10px; font-size: 10px; }

/* 1. header */
.efx-head { border-bottom: 2.5px solid #1e3a5f; margin-bottom: 10px !important; }
.efx-head > tbody > tr > td { padding-bottom: 10px; }
.efx-logo { max-height: 56px; max-width: 170px; display: block; margin-bottom: 6px; }
.efx-seller-name { font-size: 15px; font-weight: bold; color: #1e3a5f; text-transform: uppercase; margin-bottom: 2px; }
.efx-tin { font-weight: bold; color: #1e3a5f; margin-top: 2px; }
.efx-title-cell { width: 40%; text-align: right; }
.efx-title { font-size: 22px; font-weight: bold; color: #1e3a5f; letter-spacing: 1.5px; margin-bottom: 6px; }
.efx-meta { width: auto !important; margin-left: auto !important; }
.efx-meta th { text-align: left; font-weight: normal; color: #6b7785; padding: 1px 12px 1px 0 !important; white-space: nowrap; }
.efx-meta td { text-align: right; font-weight: bold; padding: 1px 0 !important; white-space: nowrap; }

/* 2. buyer */
.efx-box { border: 1px solid #d5dce4 !important; margin-bottom: 12px !important; }
.efx-box > tbody > tr > td { padding: 8px 10px !important; }
.efx-buyer-name { font-size: 12px; font-weight: bold; color: #1e3a5f; margin: 1px 0 2px; }
.efx-buyer-right { width: 30%; text-align: right; }

/* 3. items */
.efx-items thead th { background: #1e3a5f !important; color: #fff; font-size: 9px; font-weight: bold; text-transform: uppercase;
  letter-spacing: .4px; padding: 6px 6px !important; text-align: left; }
.efx-items thead th.r { text-align: right; }
.efx-items thead th.c { text-align: center; }
.efx-items tbody td { padding: 6px 6px !important; border-bottom: 1px solid #e4e9ef !important; }
.efx-items tbody tr:nth-child(even) td { background: #f7f9fb !important; }
.efx-note { font-size: 8.5px; color: #7b8794; text-align: right; margin: 3px 0 10px; }

/* 4. tax + totals */
.efx-lower { margin-top: 4px !important; page-break-inside: avoid; }
.efx-taxcol { padding-right: 16px !important; }
.efx-totcol { width: 36%; }
.efx-tax { margin-top: 3px !important; }
.efx-tax th { font-size: 8.5px; font-weight: bold; color: #6b7785; text-transform: uppercase; padding: 4px 5px !important;
  border-bottom: 1px solid #c9d2dc !important; text-align: left; }
.efx-tax th.r { text-align: right; }
.efx-tax th.c { text-align: center; }
.efx-tax td { padding: 4px 5px !important; border-bottom: 1px solid #e4e9ef !important; }
.efx-words { font-style: italic; margin-top: 2px; }
/* totals: dotted rows, teal accents, bold total with a side bar and thick underline */
.efx-totals { border-top: 2px dashed #0f7f7f !important; }
.efx-totals th { text-align: left; font-weight: normal; color: #1f2933; font-size: 11px; padding: 8px 2px !important;
  border-bottom: 1.5px dotted #4b5563 !important; }
.efx-totals td { text-align: right; font-weight: bold; color: #1f2933; font-size: 11.5px; white-space: nowrap; padding: 8px 2px !important;
  border-bottom: 1.5px dotted #4b5563 !important; }
.efx-totals tr:nth-child(even) th, .efx-totals tr:nth-child(even) td { border-bottom-color: #0f9fb0 !important; }
.efx-totals .efx-grand th, .efx-totals .efx-grand td { font-size: 13px; font-weight: bold; color: #111 !important; padding: 10px 2px 7px !important;
  border-bottom: 3.5px solid #0f7f7f !important; background: none !important; }
.efx-grand-bar { display: inline-block; width: 5px; height: 15px; background: #0f7f7f; vertical-align: -2px; margin-right: 8px; }

.efx-remarks { margin-top: 10px; }

/* 5. fiscal details (bottom) */
.efx-fiscal { margin-top: 16px !important; border: 1.5px solid #1e3a5f !important; page-break-inside: avoid; }
.efx-fiscal-fields { padding: 10px 12px !important; }
.efx-fiscal-title { font-size: 10px; font-weight: bold; color: #1e3a5f; text-transform: uppercase; letter-spacing: 1px;
  border-bottom: 1px solid #d5dce4; padding-bottom: 4px; margin-bottom: 4px; }
.efx-kv th { text-align: left; font-weight: normal; color: #6b7785; width: 44%; padding: 3px 8px 3px 0 !important; }
.efx-kv td { padding: 3px 0 !important; font-weight: bold; }
.efx-code { font-family: "Courier New", monospace; font-size: 12px; letter-spacing: .5px; color: #000; word-break: break-all; }
.efx-verify { font-size: 8.5px; color: #6b7785; margin-top: 6px; }
.efx-qr-cell { width: 140px; text-align: center; vertical-align: middle !important; padding: 8px !important; border-left: 1px solid #d5dce4 !important; }
.efx-qr { width: 118px; height: 118px; display: block; margin: 0 auto; }
.efx-qr-hint { font-size: 8.5px; color: #6b7785; margin-top: 2px; }
